//check loginCookie
var wt_loginCookie = function(conf){
	if(conf.mode == "page" && conf.type == "before" && conf.requestCounter == 1) {
		if (conf.instance && conf.instance.customParameter && !conf.instance.customParameter[23]) {
			conf.instance.customParameter[23] = (document.cookie.indexOf("zeit_sso_201501") >= 0) ? "angemeldet" : "nicht_angemeldet";
		}
	}
}

var wt_urlHashParser = function(conf){
	if(conf.mode == "page" && conf.type == "before" && conf.requestCounter == 1){
		// only execute Code when is PageView and before Tracking Request
		// mediaCode from Hash to campaignId
		// media Code > xing share
		this.urlHashParam = function(d, c, b) {
            if (!d || null === d || "undefined" === typeof d) return b;
            var f = [];
            0 <= d.indexOf("#") && (f = d.split("#")[1].replace(/&amp;/g, "&").split("&"));
            for (d = 0; d < f.length; d++)
                if (0 === f[d].indexOf(c + "=")) return f[d].substring(c.length + 1);
            return b
        }
		var xingParam = this.urlParam(document.location.href,"xing_share", ""),
			mediaCodeHash = this.urlHashParam(document.location.hash,this.config.mediaCode, ""),
			mediaCodeParam = this.urlParam(document.location.href,this.config.mediaCode, ""),
			mediaCode = mediaCodeHash || mediaCodeParam;
		
		if (mediaCode || xingParam){
			this.config.campaignId = mediaCode?this.wtEscape(this.config.mediaCode + "="+mediaCode):this.wtEscape(this.config.mediaCode + "=xing_share_"+xingParam);
		}        
    }
};

